findings.suggestion:
  const { sha, prUrl } = merge;
  let leftBehind = 0;
  let refused: unknown;
  try {
    leftBehind = isDeleted ? 0 : commitsPastPin(repoPath, `refs/heads/${session.branch}`, sha);
  } catch (error) {
    // The target already holds `sha`: record the merge first, then let the refusal go on.
    refused = error;
  }
  if (leftBehind > 0) {
    console.error(
      `${sanitizeReason(session.branch)} moved after the gate pinned ${sha}: ${leftBehind} ` +
        `later commit${leftBehind === 1 ? ' was' : 's were'} left behind on it, not merged.`,
    );
  }
  appendEvent(db, session.id, 'merge', {
    branch: session.branch,
    sha,
    target: merge.target,
    files: merge.files,
    ...(prUrl !== undefined ? { prUrl } : {}),
    ...(leftBehind > 0 ? { leftBehind } : {}),
  });
  if (refused !== undefined) throw refused;
}
